CREATE TABLE addresses ( address_id TEXT PRIMARY KEY, address1 TEXT, address2 TEXT, address3 TEXT, city TEXT, state TEXT, postal_code TEXT, customer_name TEXT, customer_phone TEXT, latitude REAL, longitude REAL, first_seen_day TEXT NOT NULL, last_seen_day TEXT NOT NULL );
CREATE TABLE breaks ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, itinerary_id TEXT NOT NULL, transporter_id TEXT NOT NULL, ordinal INTEGER NOT NULL, planned INTEGER NOT NULL CHECK(planned IN (0,1)), break_id TEXT, kind TEXT, state TEXT, sequence INTEGER, punch_id TEXT, started_at INTEGER, ended_at INTEGER, planned_start_at INTEGER, planned_end_at INTEGER, min_duration_ms INTEGER, PRIMARY KEY(publication_id,itinerary_id,planned,ordinal) );
CREATE TABLE driver_days ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, transporter_id TEXT NOT NULL, itinerary_id TEXT NOT NULL, route_code TEXT, departed_at INTEGER, first_stop_at INTEGER, last_stop_at INTEGER, session_end_at INTEGER, stops_total INTEGER NOT NULL, stops_completed INTEGER NOT NULL, tasks_total INTEGER NOT NULL, delivered INTEGER NOT NULL, picked_up INTEGER NOT NULL, not_delivered INTEGER NOT NULL, breaks_secs INTEGER, overtime_secs INTEGER, PRIMARY KEY(publication_id,itinerary_id) );
CREATE TABLE drivers ( transporter_id TEXT PRIMARY KEY, first_name TEXT, last_name TEXT, initials TEXT, work_phone TEXT, person_type TEXT NOT NULL CHECK(json_valid(person_type)), company_id TEXT, first_seen_day TEXT NOT NULL, last_seen_day TEXT NOT NULL );
CREATE TABLE itineraries ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, itinerary_id TEXT NOT NULL, transporter_id TEXT NOT NULL, driver_name TEXT NOT NULL, route_code TEXT, route_id TEXT, company_id TEXT, vin TEXT, service_type TEXT, execution_status TEXT, progress_status TEXT, planned_departure_at INTEGER, departed_at INTEGER, started_at INTEGER, wave_start_at INTEGER, session_end_at INTEGER, projected_completion_at INTEGER, last_stop_at INTEGER, block_minutes INTEGER, total_locations INTEGER, completed_locations INTEGER, total_packages INTEGER, delivered INTEGER, remaining INTEGER, undeliverable INTEGER, stops_impacted INTEGER, packages_impacted INTEGER, breaks_secs INTEGER, overtime_secs INTEGER, stop_completion_rate REAL, breaks TEXT NOT NULL CHECK(json_valid(breaks)), planned_breaks TEXT NOT NULL CHECK(json_valid(planned_breaks)), summary TEXT NOT NULL CHECK(json_valid(summary)), rescue_actions TEXT, sequence_edits TEXT, pause_events TEXT, PRIMARY KEY(publication_id,itinerary_id) );
CREATE TABLE route_publications ( id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE, day TEXT NOT NULL, station TEXT NOT NULL, service_area_id TEXT NOT NULL, provider TEXT NOT NULL, timezone TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('final','snapshot')), started_at TEXT NOT NULL, collected_at TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)), route_count INTEGER NOT NULL, itinerary_count INTEGER NOT NULL, stop_count INTEGER NOT NULL, task_count INTEGER NOT NULL, adapter_version INTEGER NOT NULL );
CREATE TABLE route_raw ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, name TEXT NOT NULL, encoding TEXT NOT NULL CHECK(encoding='gzip'), raw_bytes INTEGER NOT NULL, body BLOB NOT NULL, PRIMARY KEY(publication_id,name) );
CREATE TABLE routedata_schema (version INTEGER PRIMARY KEY CHECK(version=1));
CREATE TABLE routes ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, route_id TEXT NOT NULL, rms_route_id TEXT, route_code TEXT, company_id TEXT, service_type TEXT, route_status TEXT, progress_status TEXT, planned_departure_at INTEGER, created_at INTEGER, duration_secs INTEGER, total_stops INTEGER, total_tasks INTEGER, unassigned_stops INTEGER, unassigned_packages INTEGER, late_departing INTEGER, pre_dispatch INTEGER, same_day INTEGER, transporter_ids TEXT NOT NULL CHECK(json_valid(transporter_ids)), summary TEXT NOT NULL CHECK(json_valid(summary)), PRIMARY KEY(publication_id,route_id) );
CREATE TABLE schema_migrations (id INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at INTEGER NOT NULL);
CREATE TABLE stops ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, itinerary_id TEXT NOT NULL, stop_id TEXT NOT NULL, sequence INTEGER, address_id TEXT, stop_type TEXT, route_code TEXT, planned_start_at INTEGER, planned_end_at INTEGER, expected_start_at INTEGER, actual_start_at INTEGER, flags TEXT NOT NULL CHECK(json_valid(flags)), PRIMARY KEY(publication_id,itinerary_id,stop_id) );
CREATE TABLE storage_identity (dsp_id TEXT NOT NULL, provider TEXT NOT NULL, source TEXT NOT NULL);
CREATE TABLE tasks ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, itinerary_id TEXT NOT NULL, stop_id TEXT NOT NULL, task_id TEXT NOT NULL, transporter_id TEXT NOT NULL, tracking_id TEXT, order_id TEXT, task_type TEXT, task_state TEXT, state_context TEXT, execution_status TEXT, address_id TEXT, window_start_at INTEGER, window_end_at INTEGER, executed_at INTEGER, latitude REAL, longitude REAL, box_type TEXT, weight REAL, weight_unit TEXT, length REAL, width REAL, height REAL, volume_unit TEXT, time_windowed INTEGER, high_value INTEGER, customer_return INTEGER, address_type TEXT, events TEXT NOT NULL CHECK(json_valid(events)), active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(publication_id,task_id) );
CREATE TABLE unknown_stops ( publication_id TEXT NOT NULL REFERENCES route_publications(id) ON DELETE CASCADE, day TEXT NOT NULL, itinerary_id TEXT NOT NULL, transporter_id TEXT NOT NULL, ordinal INTEGER NOT NULL, entered_at INTEGER, exited_at INTEGER, enter_latitude REAL, enter_longitude REAL, exit_latitude REAL, exit_longitude REAL, PRIMARY KEY(publication_id,itinerary_id,ordinal) );
CREATE UNIQUE INDEX active_route_day ON route_publications(day,station,service_area_id,provider) WHERE active=1;
CREATE INDEX breaks_day ON breaks(day,transporter_id);
CREATE INDEX driver_days_day ON driver_days(day,transporter_id);
CREATE INDEX itineraries_day_driver ON itineraries(day,transporter_id);
CREATE INDEX route_publications_day ON route_publications(day,collected_at DESC);
CREATE INDEX routes_day ON routes(day,route_code);
CREATE INDEX stops_address ON stops(address_id);
CREATE INDEX tasks_address ON tasks(address_id);
CREATE INDEX tasks_day_driver ON tasks(day,transporter_id);
CREATE INDEX tasks_itinerary ON tasks(publication_id,itinerary_id);
CREATE INDEX tasks_tracking ON tasks(tracking_id);
CREATE INDEX unknown_stops_day ON unknown_stops(day,transporter_id);
CREATE VIEW deliveries AS SELECT t.day, t.transporter_id, i.driver_name, i.route_code, t.itinerary_id, t.stop_id, t.task_id, t.tracking_id, t.order_id, t.task_type, t.task_state, t.state_context, t.execution_status, t.executed_at, t.window_start_at, t.window_end_at, t.latitude scan_latitude, t.longitude scan_longitude, t.address_id, a.address1, a.city, a.state, a.postal_code, a.latitude address_latitude, a.longitude address_longitude, t.address_type, t.box_type, t.weight, t.active, t.publication_id FROM tasks t LEFT JOIN itineraries i ON i.publication_id=t.publication_id AND i.itinerary_id=t.itinerary_id LEFT JOIN addresses a ON a.address_id=t.address_id;
CREATE VIEW driver_stops AS SELECT s.day, i.transporter_id, i.driver_name, s.route_code, s.itinerary_id, s.stop_id, s.sequence, s.stop_type, s.planned_start_at, s.planned_end_at, s.address_id, a.address1, a.city, a.state, a.postal_code, a.latitude, a.longitude, (SELECT count(*) FROM tasks t WHERE t.publication_id=s.publication_id AND t.itinerary_id=s.itinerary_id AND t.stop_id=s.stop_id) tasks, (SELECT count(*) FROM tasks t WHERE t.publication_id=s.publication_id AND t.itinerary_id=s.itinerary_id AND t.stop_id=s.stop_id AND t.task_state='DELIVERED') delivered, (SELECT min(executed_at) FROM tasks t WHERE t.publication_id=s.publication_id AND t.itinerary_id=s.itinerary_id AND t.stop_id=s.stop_id) first_scan_at, (SELECT max(executed_at) FROM tasks t WHERE t.publication_id=s.publication_id AND t.itinerary_id=s.itinerary_id AND t.stop_id=s.stop_id) last_scan_at, s.flags, s.publication_id FROM stops s JOIN itineraries i ON i.publication_id=s.publication_id AND i.itinerary_id=s.itinerary_id LEFT JOIN addresses a ON a.address_id=s.address_id;
